from sympy import symbols, diff, simplify, log, tan, sec

x = symbols("x")

F = log(sec(x) + tan(x))
print(f"Example 1: d/dx {F} = sec x: {simplify(diff(F, x) - sec(x)) == 0}")
G = (sec(x) * tan(x) + log(sec(x) + tan(x))) / 2
print(f"Example 5: d/dx of the sec^3 formula = sec^3 x: {simplify(diff(G, x) - sec(x)**3) == 0}")

def tan_power(m):
    if m == 0:
        print("  integral of tan^0 = x")
        return x
    if m == 1:
        print("  integral of tan^1 = log(sec(x))")
        return log(sec(x))
    print(f"  integral of tan^{m} = {tan(x)**(m - 1) / (m - 1)} - integral of tan^{m - 2}")
    return tan(x)**(m - 1) / (m - 1) - tan_power(m - 2)

for m in [2, 3, 4, 5]:
    print(f"tan^{m} x:")
    answer = tan_power(m)
    print(f"  answer: {answer} + C, checks: {simplify(diff(answer, x) - tan(x)**m) == 0}")

