from sympy import symbols, log, tan, sec

x = symbols("x")

def tan_power(m):
    if m == 0:
        print("  integral of tan^0 = x")
        return x
    if m == 1:
        print("  integral of tan^1 = log(sec(x))")
        return log(sec(x))
    print(f"  integral of tan^{m} = {tan(x)**(m - 1) / (m - 1)} - integral of tan^{m - 2}")
    return tan(x)**(m - 1) / (m - 1) - tan_power(m - 2)

n_problems = int(input())
for p in range(1, n_problems + 1):
    m = int(input())
    print(f"problem {p}: tan^{m} x")
    print(f"  answer: {tan_power(m)} + C")
